// Package delivery owns the delivery-result record contract: the fields registered
// after every real delivery attempt and the rules every record must satisfy.
package delivery

import (
	"errors"
	"strings"
	"time"
)

// Sentinel validation errors. The HTTP layer maps them to the published error codes.
var (
	ErrInvalidRecord = errors.New("invalid delivery record")
	ErrInvalidQuery  = errors.New("invalid delivery query")
)

// Allowed delivery channels.
var channels = map[string]struct{}{
	"sms":    {},
	"email":  {},
	"push":   {},
	"in_app": {},
}

// IsAllowedChannel reports whether channel is one the service can register.
func IsAllowedChannel(channel string) bool {
	_, ok := channels[channel]
	return ok
}

// IsAllowedStatus reports whether status is one of the four published states.
func IsAllowedStatus(status string) bool {
	switch status {
	case StatusPending, StatusRetrying, StatusSucceeded, StatusFailed:
		return true
	}
	return false
}

// Published delivery statuses.
const (
	StatusPending   = "pending"
	StatusRetrying  = "retrying"
	StatusSucceeded = "succeeded"
	StatusFailed    = "failed"
)

// RecordInput is the payload submitted through the public write entry.
// RetryCount is a pointer so a missing or null value is rejected the same
// way as a non-integer value.
type RecordInput struct {
	TemplateID    string `json:"template_id"`
	Channel       string `json:"channel"`
	OccurredAt    string `json:"occurred_at"`
	Status        string `json:"status"`
	RetryCount    *int   `json:"retry_count"`
	FailureReason string `json:"failure_reason"`
}

// Record is a successfully registered delivery attempt. Every attempt is an
// independent row; repeated notifications never overwrite earlier records.
type Record struct {
	ID            string    `json:"id"`
	TemplateID    string    `json:"template_id"`
	Channel       string    `json:"channel"`
	OccurredAt    time.Time `json:"occurred_at"`
	Status        string    `json:"status"`
	RetryCount    int       `json:"retry_count"`
	FailureReason string    `json:"failure_reason"`
}

// NewRecord validates input and builds the record as it will be stored. The id
// is assigned by the storage layer when the insert actually succeeds.
func NewRecord(in RecordInput) (Record, error) {
	templateID := strings.TrimSpace(in.TemplateID)
	if templateID == "" {
		return Record{}, ErrInvalidRecord
	}
	if !IsAllowedChannel(strings.TrimSpace(in.Channel)) || in.Channel != strings.TrimSpace(in.Channel) {
		return Record{}, ErrInvalidRecord
	}
	occurredAt, err := time.Parse(time.RFC3339, in.OccurredAt)
	if err != nil {
		return Record{}, ErrInvalidRecord
	}
	if !IsAllowedStatus(in.Status) {
		return Record{}, ErrInvalidRecord
	}
	if in.RetryCount == nil || *in.RetryCount < 0 {
		return Record{}, ErrInvalidRecord
	}
	switch in.Status {
	case StatusFailed, StatusRetrying:
		if strings.TrimSpace(in.FailureReason) == "" {
			return Record{}, ErrInvalidRecord
		}
	case StatusPending, StatusSucceeded:
		if in.FailureReason != "" {
			return Record{}, ErrInvalidRecord
		}
	}
	return Record{
		TemplateID:    templateID,
		Channel:       in.Channel,
		OccurredAt:    occurredAt.UTC(),
		Status:        in.Status,
		RetryCount:    *in.RetryCount,
		FailureReason: in.FailureReason,
	}, nil
}

// Query is a validated channel plus half-open time range query.
type Query struct {
	Channel string
	Start   time.Time
	End     time.Time
}

// NewQuery validates the query parameters. The range is [start, end), so start
// must be strictly before end.
func NewQuery(channel, startRaw, endRaw string) (Query, error) {
	if !IsAllowedChannel(strings.TrimSpace(channel)) || channel != strings.TrimSpace(channel) {
		return Query{}, ErrInvalidQuery
	}
	start, err := time.Parse(time.RFC3339, startRaw)
	if err != nil {
		return Query{}, ErrInvalidQuery
	}
	end, err := time.Parse(time.RFC3339, endRaw)
	if err != nil {
		return Query{}, ErrInvalidQuery
	}
	if !start.Before(end) {
		return Query{}, ErrInvalidQuery
	}
	return Query{
		Channel: channel,
		Start:   start.UTC(),
		End:     end.UTC(),
	}, nil
}
package delivery

import (
	"errors"
	"strings"
	"time"
)

// ErrInvalidOverview marks a failed attempt-overview parameter validation. The
// HTTP layer maps it to the published INVALID_DELIVERY_OVERVIEW error code.
var ErrInvalidOverview = errors.New("invalid delivery attempt overview")

// OverviewInput carries the raw attempt-overview parameters as received on the
// query string. The pointer field distinguishes an omitted template_id from an
// empty one: a present but blank value is invalid, while nil means the filter
// is unused.
type OverviewInput struct {
	Channel    string
	Start      string
	End        string
	TemplateID *string
}

// OverviewQuery is the validated attempt-overview query. It shares the channel
// and half-open [Start, End) semantics with the basic list query and adds an
// optional exact template identifier filter.
type OverviewQuery struct {
	Channel    string
	Start      time.Time
	End        time.Time
	TemplateID *string
}

// StatusCounts always carries all four published statuses. A status that never
// occurred in the queried range keeps a zero count.
type StatusCounts struct {
	Pending   int `json:"pending"`
	Retrying  int `json:"retrying"`
	Succeeded int `json:"succeeded"`
	Failed    int `json:"failed"`
}

// OverviewLastAttempt is the most recent registered attempt of one template:
// the greatest occurred_at wins and ties break on the greatest id.
type OverviewLastAttempt struct {
	ID            string    `json:"id"`
	OccurredAt    time.Time `json:"occurred_at"`
	Status        string    `json:"status"`
	RetryCount    int       `json:"retry_count"`
	FailureReason string    `json:"failure_reason"`
}

// OverviewGroup aggregates every registered attempt of one template within the
// queried channel and half-open time range.
type OverviewGroup struct {
	TemplateID     string              `json:"template_id"`
	TotalAttempts  int                 `json:"total_attempts"`
	RetryCountMin  int                 `json:"retry_count_min"`
	RetryCountMax  int                 `json:"retry_count_max"`
	StatusCounts   StatusCounts        `json:"status_counts"`
	LastAttempt    OverviewLastAttempt `json:"last_attempt"`
	FailureReasons []FailureGroup      `json:"failure_reasons"`
}

// NewOverview validates the attempt-overview parameters. The overview only
// reads registered records; it never writes, completes or modifies anything.
func NewOverview(in OverviewInput) (OverviewQuery, error) {
	if !IsAllowedChannel(strings.TrimSpace(in.Channel)) || in.Channel != strings.TrimSpace(in.Channel) {
		return OverviewQuery{}, ErrInvalidOverview
	}
	start, err := time.Parse(time.RFC3339, in.Start)
	if err != nil {
		return OverviewQuery{}, ErrInvalidOverview
	}
	end, err := time.Parse(time.RFC3339, in.End)
	if err != nil {
		return OverviewQuery{}, ErrInvalidOverview
	}
	if !start.Before(end) {
		return OverviewQuery{}, ErrInvalidOverview
	}
	query := OverviewQuery{
		Channel: in.Channel,
		Start:   start.UTC(),
		End:     end.UTC(),
	}
	if in.TemplateID != nil {
		templateID := strings.TrimSpace(*in.TemplateID)
		if templateID == "" {
			return OverviewQuery{}, ErrInvalidOverview
		}
		query.TemplateID = &templateID
	}
	return query, nil
}
package delivery

import (
	"errors"
	"strings"
	"time"
)

// ErrInvalidSummary marks a failed failure-summary parameter validation. The
// HTTP layer maps it to the published INVALID_DELIVERY_SUMMARY error code.
